CREATE TABLE IF NOT EXISTS public.ai_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor text NOT NULL, type text NOT NULL DEFAULT 'openai', active boolean NOT NULL DEFAULT true, priority integer NOT NULL DEFAULT 0, api_key text, config jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now()); CREATE TABLE IF NOT EXISTS public.ai_models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid REFERENCES public.ai_providers(id) ON DELETE CASCADE, model_id text NOT NULL, label text NOT NULL, tier text NOT NULL DEFAULT 'standard', active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now()); CREATE TABLE IF NOT EXISTS public.ai_feature_settings (feature_key text PRIMARY KEY, provider_id uuid REFERENCES public.ai_providers(id) ON DELETE SET NULL, model_id text, enabled boolean NOT NULL DEFAULT true, credits integer NOT NULL DEFAULT 1, max_input_tokens integer NOT NULL DEFAULT 8000, max_output_tokens integer NOT NULL DEFAULT 4000, daily_limit integer, monthly_limit integer, updated_at timestamptz DEFAULT now()); CREATE TABLE IF NOT EXISTS public.ai_provider_pricing (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, model text NOT NULL, input_price_per_1k numeric NOT NULL DEFAULT 0, output_price_per_1k numeric NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS public.ai_provider_budgets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, monthly_budget numeric NOT NULL DEFAULT 0, warning_threshold numeric NOT NULL DEFAULT 80, hard_limit numeric NOT NULL DEFAULT 100, current_spend numeric NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS public.ai_provider_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, model text NOT NULL, date date NOT NULL DEFAULT CURRENT_DATE, requests integer NOT NULL DEFAULT 0, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, estimated_cost numeric NOT NULL DEFAULT 0); GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_providers TO authenticated; GRANT ALL ON public.ai_providers TO service_role; ALTER TABLE public.ai_providers ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins manage AI providers" ON public.ai_providers; CREATE POLICY "Admins manage AI providers" ON public.ai_providers FOR ALL TO authenticated USING (private.has_role(auth.uid(), 'admin')); GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_models TO authenticated; GRANT ALL ON public.ai_models TO service_role; ALTER TABLE public.ai_models ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins manage AI models" ON public.ai_models; CREATE POLICY "Admins manage AI models" ON public.ai_models FOR ALL TO authenticated USING (private.has_role(auth.uid(), 'admin')); GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_feature_settings TO authenticated; GRANT ALL ON public.ai_feature_settings TO service_role; ALTER TABLE public.ai_feature_settings ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins manage AI feature settings" ON public.ai_feature_settings; CREATE POLICY "Admins manage AI feature settings" ON public.ai_feature_settings FOR ALL TO authenticated USING (private.has_role(auth.uid(), 'admin')); GRANT SELECT ON public.ai_provider_pricing TO authenticated; GRANT ALL ON public.ai_provider_pricing TO service_role; ALTER TABLE public.ai_provider_pricing ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins manage AI pricing" ON public.ai_provider_pricing; CREATE POLICY "Admins manage AI pricing" ON public.ai_provider_pricing FOR ALL TO authenticated USING (private.has_role(auth.uid(), 'admin')); GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_provider_budgets TO authenticated; GRANT ALL ON public.ai_provider_budgets TO service_role; ALTER TABLE public.ai_provider_budgets ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins manage AI budgets" ON public.ai_provider_budgets; CREATE POLICY "Admins manage AI budgets" ON public.ai_provider_budgets FOR ALL TO authenticated USING (private.has_role(auth.uid(), 'admin')); GRANT SELECT ON public.ai_provider_usage TO authenticated; GRANT ALL ON public.ai_provider_usage TO service_role; ALTER TABLE public.ai_provider_usage ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins view AI usage" ON public.ai_provider_usage; CREATE POLICY "Admins view AI usage" ON public.ai_provider_usage FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin')); INSERT INTO public.ai_feature_settings (feature_key, enabled, credits) VALUES ('topic_generation', true, 1), ('chapter_generation', true, 2), ('refinement', true, 2), ('academic_assist', true, 1), ('citation', true, 1), ('quality_check', true, 1), ('defense_basic', true, 1), ('defense_simulation', true, 3), ('originality', true, 2), ('literature', true, 2), ('data_analysis', true, 2) ON CONFLICT (feature_key) DO NOTHING;